    { t: "van den Oord, A. et al. (2016). WaveNet: A Generative Model for Raw Audio", u: "https://arxiv.org/abs/1609.03499" },
    { t: "van den Oord, A. et al. (2017). Parallel WaveNet: Fast High-Fidelity Speech Synthesis", u: "https://arxiv.org/abs/1711.10433" },
    { t: "Shen, J. et al. (2017). Natural TTS Synthesis by Conditioning WaveNet on Mel Spectrogram Predictions", u: "https://arxiv.org/abs/1712.05884" },
    { t: "Campbell, J. P. (1997). Speaker recognition: a tutorial", u: "https://doi.org/10.1109/5.628714" },
    { t: "Snyder, D. et al. (2018). X-Vectors: Robust DNN Embeddings for Speaker Recognition", u: "https://doi.org/10.1109/ICASSP.2018.8461375" },
    { t: "El Ayadi, M., Kamel, M. S. & Karray, F. (2011). Survey on speech emotion recognition: Features, classification schemes, and databases", u: "https://doi.org/10.1016/j.patcog.2010.09.020" }
